<script lang="ts">
 import {onMount} from 'svelte';import {Button} from '$lib/components/ui/button';import {FolderOpen,ArrowUpRight,Plus,Clapperboard,Users,ListVideo,Image,Coins} from '@lucide/svelte';import {request} from './api';import {selectStudioProject,studioHref} from './navigation';import GenerationJobs from './GenerationJobs.svelte';
 let {user}:{user:any}=$props();let projects=$state<any[]>([]),jobs=$state<any[]>([]),credits=$state<any>(null),project=$state(''),loading=$state(true),error=$state('');let alive=true;
 const current=$derived(projects.find(p=>p.id===project));
 onMount(()=>{void load();return()=>{alive=false;};});
 async function load(){loading=true;error='';try{const [p,j,c]=await Promise.allSettled([request('/projects'),request('/jobs'),request('/credits')]);if(!alive)return;if(p.status==='rejected')throw p.reason;projects=p.value;project=selectStudioProject(projects,project,localStorage.getItem(`videoflow.cloud.project.${user.id}`));if(j.status==='fulfilled')jobs=j.value.slice(0,4);if(c.status==='fulfilled')credits=c.value;}catch(e){if(alive)error=(e as Error).message;}finally{if(alive)loading=false;}}
 function choose(id:string){project=id;localStorage.setItem(`videoflow.cloud.project.${user.id}`,id);}
</script>
<div class="studio-dashboard"><header class="dashboard-heading"><div><h1>Your studio</h1><p>A place for your next video.</p></div><Button href="/projects"><Plus class="size-4"/>New project</Button></header>
{#if error}<div class="cloud-alert" role="alert">{error}<Button variant="ghost" onclick={load}>Try again</Button></div>{/if}
{#if loading}<div class="dashboard-loading" role="status">Loading your studio…</div>{:else}
{#if current}<section class="continue-project" aria-label="Continue your project"><div class="continue-copy"><h2>{current.name}</h2><p>{current.description||'Arrange your story, shape the cast and bring your scenes together.'}</p><Button href={`/studio?project=${encodeURIComponent(project)}`}><Clapperboard class="size-4"/>Open canvas<ArrowUpRight class="size-4"/></Button></div><div class="project-tools"><label for="dashboard-project">Current project</label><select id="dashboard-project" value={project} onchange={e=>choose(e.currentTarget.value)}>{#each projects as item}<option value={item.id}>{item.name}</option>{/each}</select><nav aria-label="Current project tools">{#each [{kind:'characters',label:'Characters',icon:Users},{kind:'scenes',label:'Scenes',icon:ListVideo},{kind:'assets',label:'Assets',icon:Image}] as item}<a href={studioHref(item.kind,project)}><item.icon class="size-4"/>{item.label}<ArrowUpRight class="size-3.5"/></a>{/each}</nav></div></section>
{:else}<section class="dashboard-start"><FolderOpen class="size-8"/><h2>Start with a project</h2><p>Keep your scenes, characters and finished video together.</p><Button href="/projects">Create your first project<Plus class="size-4"/></Button></section>{/if}
<div class="dashboard-columns"><section class="dashboard-projects"><div class="dashboard-section-heading"><h2>Recent projects</h2><a href="/projects">All projects<ArrowUpRight class="size-3.5"/></a></div>{#each projects.slice(0,5) as item}<a class="dashboard-project-row" href={`/studio?project=${encodeURIComponent(item.id)}`}><FolderOpen class="size-4"/><span>{item.name}<small>{new Date(item.created_at).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</small></span><ArrowUpRight class="size-4"/></a>{:else}<p class="dashboard-muted">Your projects will appear here.</p>{/each}</section><aside class="dashboard-account"><h2>Ready to publish?</h2><p>Share a finished video or manage the videos already on your channel.</p><Button variant="outline" href="/channel">My content<ArrowUpRight class="size-4"/></Button><a class="dashboard-balance" href="/credits"><Coins class="size-4"/><span>{credits?`${Number(credits.available??0).toLocaleString()} credits available`:'View generation credits'}</span><ArrowUpRight class="size-3.5"/></a></aside></div>
<GenerationJobs {jobs} onrefresh={async()=>{jobs=(await request('/jobs')).slice(0,4);}}/>
{/if}</div>
<style>.studio-dashboard{max-width:1120px;margin:0 auto}.dashboard-heading{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:36px}.dashboard-heading h1{font-size:26px;font-weight:600;letter-spacing:-.03em}.dashboard-heading p{font-size:13px;color:var(--muted-foreground);margin-top:8px}.continue-project{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(220px,1fr);gap:48px;padding:32px 0;border-block:1px solid var(--border)}.continue-copy h2{font-size:24px;font-weight:550;letter-spacing:-.02em;margin:13px 0 12px;overflow-wrap:anywhere}.continue-copy>p{font-size:13px;color:var(--muted-foreground);line-height:1.8;max-width:52ch;margin-bottom:24px}.project-tools label{margin:0 0 10px!important}.project-tools nav{display:grid;gap:4px;margin-top:18px}.project-tools nav a{display:flex;gap:10px;align-items:center;min-height:40px;padding:8px 0;font-size:13px;color:var(--muted-foreground)}.project-tools nav a:hover{color:var(--foreground)}.project-tools nav a :global(svg:last-child){margin-left:auto}.dashboard-columns{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(220px,1fr);gap:48px;margin-top:36px}.dashboard-section-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}.dashboard-section-heading h2,.dashboard-account h2{font-size:15px;font-weight:550}.dashboard-section-heading>a{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted-foreground)}.dashboard-project-row{display:flex;gap:14px;align-items:center;border-bottom:1px solid var(--border);padding:18px 0;font-size:13px}.dashboard-project-row>span{flex:1;min-width:0;overflow-wrap:anywhere}.dashboard-project-row small{display:block;font-size:11px;color:var(--muted-foreground);margin-top:7px}.dashboard-project-row :global(svg){flex-shrink:0;color:var(--muted-foreground)}.dashboard-account>p{font-size:13px;line-height:1.8;color:var(--muted-foreground);margin:14px 0 20px}.dashboard-balance{display:flex;align-items:center;gap:9px;font-size:12px;color:var(--muted-foreground);border-top:1px solid var(--border);padding:20px 0;margin-top:28px}.dashboard-muted{font-size:13px;color:var(--muted-foreground);line-height:1.8}.dashboard-start{display:grid;justify-items:start;gap:18px;padding:40px 0;border-block:1px solid var(--border)}.dashboard-start h2{font-size:20px;font-weight:550}.dashboard-start p{font-size:13px;color:var(--muted-foreground)}.dashboard-loading{display:grid;place-content:center;min-height:300px;font-size:13px;color:var(--muted-foreground)}@media(max-width:650px){.dashboard-heading{align-items:start;gap:16px;margin-bottom:26px}.dashboard-heading h1{font-size:23px}.dashboard-heading :global(a){min-height:44px}.continue-project,.dashboard-columns{grid-template-columns:minmax(0,1fr);gap:28px}.continue-project{padding:26px 0}.continue-copy h2{font-size:22px}.project-tools nav{grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.project-tools nav a{font-size:12px;min-height:44px;gap:6px}.project-tools nav a :global(svg:last-child){display:none}.dashboard-account{border-top:1px solid var(--border);padding-top:26px}}
</style>
